// Fim dos Tempos · Arco 1 · Especial de Gatal · gerado por a1-especial-de-gatal.js
const DADOS = {"garbin":[["humano","um humano idoso, baixinho e gorducho, de barba branca e avental de couro"],["hynne","um hynne, sem dúvida: os pés descalços e peludos aparecem por baixo do avental"],["anao","claramente um anão, com a barba trançada e um orgulho enorme do próprio martelo"],["elfo","um elfo muito baixinho, de orelhas pontudas escondidas no gorro"],["silfide","uma sílfide! As asinhas tremulam enquanto ela ajeita um laço de fita"],["minotauro","um minotauro bonachão, com o gorro enfiado entre os chifres"],["sereia","uma sereia, de cauda e tudo, sentada num balde, dando instruções"],["goblin","um goblin velhinho e risonho, remendando a própria barba"],["kliren","um kliren de óculos grossos, que corrige a sua técnica de embrulho"],["qareen","um qareen de olhos brilhantes, que garante que não pode realizar desejos (hoje)"],["dahllan","uma dahllan de cabelos de folha, com flores brotando no gorro"],["minotauro","de novo um minotauro... ou era uma minotaura? Garbin ri e diz que tanto faz"]]};
(async function macroGarbin(D) {
		const ESTADO = "fdtGatal";
		const i = game.user.getFlag("world", `${ESTADO}.garbin`) ?? 0;
		const [raca, txt] = D.garbin[i % D.garbin.length];
		const img = `systems/tormenta20/icons/racas/${raca}.webp`;
		const ator = game.actors.find((a) => a.getFlag("world", "fdtRole") === "garbin");
		if (ator) await ator.update({ img, "prototypeToken.texture.src": img });
		const tks = canvas.tokens.placeables.filter((t) => t.actor?.getFlag("world", "fdtRole") === "garbin");
		if (tks.length) await canvas.scene.updateEmbeddedDocuments("Token", tks.map((t) => ({ _id: t.id, "texture.src": img })));
		await game.user.setFlag("world", `${ESTADO}.garbin`, i + 1);
		ChatMessage.create({ content: `<p>Vocês olham de novo para Garbin. Engraçado... agora Garbin é <b>${txt}</b>. Ninguém parece achar isso estranho, muito menos ele mesmo.</p>` });
	})(DADOS);
